function groupAnagrams(strs: string[]): string[][] {
  // Канонический ключ → все строки с этим ключом
  const groups = new Map<string, string[]>();

  for (const s of strs) {
    // Ключ — вектор частот 26 букв: у анаграмм он одинаковый
    const count = new Array<number>(26).fill(0);
    for (let i = 0; i < s.length; i++) {
      count[s.charCodeAt(i) - 97]++;
    }
    // Разделитель нужен, чтобы [1,11] и [11,1] дали разные ключи
    const key = count.join('#');

    const group = groups.get(key);
    if (group) {
      group.push(s);
    } else {
      groups.set(key, [s]);
    }
  }

  return [...groups.values()];
}

// Время: O(n · k) — n строк длины до k, плюс 26 на ключ
// Память: O(n · k) — все строки лежат в группах
